# Write your MySQL query statement below
SELECT PRICES.PRODUCT_ID ,ROUND(IFNULL(SUM(PRICES.PRICE*UNITSSOLD.UNITS)/SUM(UNITSSOLD.UNITS),0),2) AS AVERAGE_PRICE FROM PRICES LEFT JOIN UNITSSOLD  ON PRICES.PRODUCT_ID=UNITSSOLD.PRODUCT_ID AND UNITSSOLD.PURCHASE_DATE BETWEEN PRICES.START_DATE AND PRICES.END_DATE GROUP BY PRICES.PRODUCT_ID;